/// <summary>
/// Method to save METScanSupplier field to Sales Order type in case the Transaction is created from Sales order.
/// </summary>
/// <param name="sender">Get Table buffer</param>
/// <param name="e"> Get table event args</param>
[DataEventHandler(tableStr(TAMRebateTrans), DataEventType::Inserting)]
public static void TAMRebateTrans_onInserting(Common sender, DataEventArgs e)
{
    TAMRebateTrans rebateTrans = sender as TAMRebateTrans;
    if(rebateTrans.RebateRefId)
    {
        rebateTrans.METScanSupplier = METScanSupplier::SalesOrder;
    }
}

/// <summary>
/// When Rebate transactions are deleted, related Scan/Supplier records are marked as Unprocessed
/// </summary>
/// <param name="sender">Get Table buffer</param>
/// <param name="e"> Get table event args</param>>
[DataEventHandler(tableStr(TAMRebateTrans), DataEventType::Deleting)]
public static void TAMRebateTrans_onDeleting(Common sender, DataEventArgs e)
{
    TAMRebateTrans rebateTrans = sender as TAMRebateTrans;
    if(rebateTrans.METRebateScanSupplierTable)
    {
        METRebateScanSupplierTable      rebateScanSupplierTable;
        ttsbegin;
        select forupdate firstonly1 rebateScanSupplierTable where rebateScanSupplierTable.RecId == rebateTrans.METRebateScanSupplierTable;
        rebateScanSupplierTable.Processed = NoYes::No;
        if(rebateScanSupplierTable.validateWrite())
        {
            rebateScanSupplierTable.update();
        }
        ttscommit;
    }
}
